function() {
function mapPinterestLineItems(products) {
  products = products || [];
  if (typeof products.map !== 'function') return [];
  return products.map(function(product) {
    product = product || {};
    var price = Number(product.price || product.product_price || product.item_price || 0);
    var qty = Number(product.quantity || product.product_quantity || 1);
    if (!isFinite(price) || price < 0) price = 0;
    if (!isFinite(qty) || qty <= 0) qty = 1;
    return {
      product_name: product.name || product.product_name || product.item_name || undefined,
      product_variant: product.variant || product.product_variant || undefined,
      product_id: product.product_id || product.id || product.item_id || product.sku || product.variant_id || undefined,
      product_variant_id: product.variant_id || product.product_variant_id || undefined,
      product_category: product.category || product.product_category || product.item_category || undefined,
      product_brand: product.brand || product.product_brand || undefined,
      product_price: price,
      product_quantity: qty
    };
  }).filter(function(item) { return item.product_id || item.product_name; });
}
  return mapPinterestLineItems({{PINTEREST ISO - DLV - Purchase Products}});
}

