function() {
  try {
    var e = {{dlv - Customer Email}} || {{dlv - Thank You Page - Customer Email}} || '';
    e = String(e).trim().toLowerCase();
    // Return empty if not a basic email format
    if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)) return undefined;
    return e; // TikTok pixel hashes client-side automatically
  } catch(e){ return undefined; }
}

function() {
  try {
    // Try to pull phone number from either data layer key
    var p = {{dlv - Customer Phone}} || {{dlv - Thank You Page - Customer Phone Number}} || '';

    // Remove all non-numeric characters
    p = String(p).replace(/[^\d]/g, '');

    // If exactly 10 digits, assume US number and prepend country code
    if (p.length === 10) p = '1' + p;

    // Validate it's now 11–15 digits (valid E.164 length)
    if (!/^\d{11,15}$/.test(p)) return undefined;

    // Return as properly formatted E.164 number
    return '+' + p;
  } catch(e) {
    return undefined;
  }
}

