function() {
  function generateUID() {
    return Math.floor(Math.random() * 9e12) + 1e12;
  }
  var cookieName = '_br_uid_2';
  var cookieMatch = document.cookie.match('(^|;)\\s*' + cookieName + '\\s*=\\s*([^;]+)');
  var cookieValue = cookieMatch ? cookieMatch.pop() : null;

  //console.log('cookieValue:', cookieValue);

  cookieValue = decodeURIComponent(cookieValue);
  //console.log('cookieValue 2:', cookieValue);

  if (!cookieValue) {
    var uid = generateUID();
    var timestamp = Math.floor(Date.now() / 1000);
    cookieValue = 'uid=' + uid + ':v=1:ts=' + timestamp + ':hc=1:generated=true';
    document.cookie = cookieName + '=' + cookieValue + '; path=/; expires=Fri, 31 Dec 9999 23:59:59 GMT';
  }

  sessionStorage.setItem(cookieName, cookieValue);

  return cookieValue;
}

function() {
  // Customize logic to return the correct page type
  var path = window.location.pathname;
  var brPageType = '';
  if (path === "/"|| path === '/index') return "homepage";
  else if (path.includes("/collections/") && !path.includes("/products/")) brPageType = "category";
  else if (path.includes("/search")) brPageType = "search";
  else if (path.includes("/products/")) brPageType = "product";
  else if (path.includes("/pages/")) brPageType = "content";
  else brPageType = "other";

  console.log ('brPageType', brPageType )
  return brPageType;
}

